cpp_src = r'''
#include <torch/extension.h>
#include <ATen/ATen.h>

torch::Tensor layernorm_forward(
    torch::Tensor input,
    torch::Tensor weight,
    torch::Tensor bias,
    float eps);

PYBIND11_MODULE(TORCH_EXTENSION_NAME, m) {
  m.def("layernorm_forward", &layernorm_forward, "LayerNorm forward (CUDA)");
}
'''

cuda_src = r'''
#include <cuda.h>
#include <cuda_runtime.h>
#include <torch/types.h>

template <int BLOCK_SIZE>
__global__ void layernorm_forward_kernel(
    const half* __restrict__ input,
    const half* __restrict__ weight,
    const half* __restrict__ bias,
    half* __restrict__ output,
    int normalized_size,
    float eps)
{
    const int batch = blockIdx.x;
    const int tid   = threadIdx.x;
    const int stride = BLOCK_SIZE;

    const half* in_ptr  = input  + (size_t)batch * normalized_size;
    const half* w_ptr   = weight;
    const half* b_ptr   = bias;
    half* out_ptr       = output + (size_t)batch * normalized_size;

    // --------- reduction for mean & variance ----------
    float sum = 0.0f;
    float sum_sq = 0.0f;

    for (int i = tid; i < normalized_size; i += stride) {
        float val = __half2float(in_ptr[i]);
        sum    += val;
        sum_sq += val * val;
    }

    __shared__ float shmem_sum[BLOCK_SIZE];
    __shared__ float shmem_sum_sq[BLOCK_SIZE];

    shmem_sum[tid]    = sum;
    shmem_sum_sq[tid] = sum_sq;
    __syncthreads();

    // parallel reduction in shared memory
    for (int offset = BLOCK_SIZE / 2; offset > 0; offset >>= 1) {
        if (tid < offset) {
            shmem_sum[tid]    += shmem_sum[tid + offset];
            shmem_sum_sq[tid] += shmem_sum_sq[tid + offset];
        }
        __syncthreads();
    }

    const float mean = shmem_sum[0] / normalized_size;
    const float var  = shmem_sum_sq[0] / normalized_size - mean * mean;
    const float inv_std = rsqrtf(var + eps);

    // --------- apply normalization ----------
    for (int i = tid; i < normalized_size; i += stride) {
        float x = __half2float(in_ptr[i]);
        float w = __half2float(w_ptr[i]);
        float b = __half2float(b_ptr[i]);
        float norm = (x - mean) * inv_std;
        float y = norm * w + b;
        out_ptr[i] = __float2half(y);
    }
}

// ---------------------------------------------------------------------
// C++ entry point
// ---------------------------------------------------------------------
torch::Tensor layernorm_forward(
    torch::Tensor input,
    torch::Tensor weight,
    torch::Tensor bias,
    float eps)
{
    TORCH_CHECK(input.is_cuda(), "input must be CUDA");
    TORCH_CHECK(weight.is_cuda(), "weight must be CUDA");
    TORCH_CHECK(bias.is_cuda(),   "bias must be CUDA");
    TORCH_CHECK(input.dtype() == torch::kHalf, "input must be fp16");
    TORCH_CHECK(weight.dtype() == torch::kHalf, "weight must be fp16");
    TORCH_CHECK(bias.dtype()   == torch::kHalf, "bias must be fp16");
    TORCH_CHECK(input.is_contiguous(), "input must be contiguous");
    TORCH_CHECK(weight.is_contiguous(), "weight must be contiguous");
    TORCH_CHECK(bias.is_contiguous(),   "bias must be contiguous");

    const auto batch = input.size(0);
    const int normalized_size = input.numel() / batch; // product of remaining dims

    auto output = torch::empty_like(input);

    const int BLOCK_SIZE = 256;
    const dim3 grid(batch);
    const dim3 block(BLOCK_SIZE);

    AT_DISPATCH_FLOATING_TYPES_AND_HALF(input.scalar_type(), "layernorm_forward_kernel", ([&] {
        layernorm_forward_kernel<BLOCK_SIZE><<<grid, block>>>(
            input.data_ptr<half>(),
            weight.data_ptr<half>(),
            bias.data_ptr<half>(),
            output.data_ptr<half>(),
            normalized_size,
            eps);
    }));

    CUDA_CHECK(cudaGetLastError());
    return output;
}
'''

# ------------------------------------------------------------------------
# Compile the extension
# ------------------------------------------------------------------------
_ext = load_inline(name='layernorm_ext',
                   cpp_sources=cpp_src,
                   cuda_sources=cuda_src,
                   functions=['layernorm_forward'],
                   verbose=False)

# ------------------------------------------------------------------------
# Python wrapper
# ------------------------------------------------------------------------
def _layernorm_forward(input: torch.Tensor,
                       weight: torch.Tensor,
                       bias: torch.Tensor,
                       eps: float) -> torch.Tensor:
    if not input.is_cuda:
        raise RuntimeError("Input must be CUDA tensor")
    if input.dtype != torch.float16:
        input = input.half()
    if weight.dtype != torch.float16:
        weight = weight.half()
    if bias.dtype != torch.float16:
        bias = bias.half()
    return _ext.layernorm_forward(input, weight, bias, eps)


# ------------------------------------------------------------------------
# Model definition using the custom kernel
# ------------------------------------------------------------------------
class ModelNew(nn.Module):
    """
    LayerNorm implemented with a custom CUDA kernel.
    Mirrors torch.nn.LayerNorm with elementwise_affine=True.
    """
    def __init__(self, normalized_shape: tuple, eps: float = 1e-5):
        super().__init__()
        self.normalized_shape = normalized_shape
        self.eps = eps
        # weight and bias have the same shape as normalized dimensions
        self.weight = nn.Parameter(torch.ones(normalized_shape,
                                              dtype=torch.float16,
                                              device='cuda'))
        self.bias   = nn.Parameter(torch.zeros(normalized_shape,
                                              dtype=torch.float16,
                                              device='cuda'))

    def forward(self, x: torch.Tensor) -> torch.Tensor:
        # ensure contiguous and correct dtype
        if not x.is_contiguous():
            x = x.contiguous()
        if x.dtype != torch.float16:
            x = x.half()
        return _layernorm_forward(x, self.weight, self.bias, self.eps)


# ------------------------------------------------------------------------
# Helper functions matching the reference script
# ------------------------------------------------------------------------
def get_inputs():
    batch_size = 16
    features = 64
    dim1 = 256
    dim2 = 256
    x = torch.rand(batch_size, features, dim1, dim2, dtype=torch.float16, device='cuda')
    return [x]

def get_init_inputs():
    # returns shape tuple for normalized dimensions (features, dim1, dim2)
    return [(64, 256, 256)]
